/** Generated by contrast-compiler/1.0.0. NOT EXECUTED by export.
 * Place in apps/web/src/lib/contrast/__tests__/exported.test.ts.
 * Run npm test --workspace=@nova/web -- --runInBand exported.test.ts
 * Adapter inputs are data. Assertions come from separately declared requirements.
 * Model-only checks are pending, not passing. Uncovered executable requirements fail. */
import { observe } from '../adapters';
import { normalize } from '../schema';
import type { TestSpec } from '../bundle';
const spec: TestSpec = {
  "version": "contrast-tests/1",
  "project": {
    "schemaVersion": "nova-contrast/1",
    "name": "Public sameness, internal difference",
    "cases": [
      {
        "id": "E",
        "name": "Earlier time"
      },
      {
        "id": "Q",
        "name": "Quiet room"
      }
    ],
    "channels": [
      {
        "id": "public",
        "name": "Public arrangement"
      },
      {
        "id": "internal",
        "name": "Internal planning"
      }
    ],
    "observations": [
      {
        "id": "arrangement",
        "name": "Visible arrangement",
        "cost": 1,
        "enabled": true,
        "channels": [
          "public"
        ],
        "kind": "categorical",
        "source": "simulated",
        "values": {
          "E": "Earlier + quiet",
          "Q": "Earlier + quiet"
        }
      },
      {
        "id": "reason",
        "name": "Private reason",
        "cost": 1,
        "enabled": true,
        "channels": [
          "public",
          "internal"
        ],
        "kind": "categorical",
        "source": "simulated",
        "values": {
          "E": "time",
          "Q": "noise"
        }
      }
    ],
    "requirements": [
      {
        "id": "public-same",
        "channel": "public",
        "kind": "same",
        "left": "E",
        "right": "Q"
      },
      {
        "id": "internal-apart",
        "channel": "internal",
        "kind": "different",
        "left": "E",
        "right": "Q"
      }
    ]
  },
  "checks": [
    {
      "id": "public-same",
      "kind": "same",
      "left": "E",
      "right": "Q",
      "channel": "public",
      "observationIds": [
        "arrangement",
        "reason"
      ],
      "executable": false,
      "modelStatus": "violation"
    },
    {
      "id": "internal-apart",
      "kind": "different",
      "left": "E",
      "right": "Q",
      "channel": "internal",
      "observationIds": [
        "reason"
      ],
      "executable": false,
      "modelStatus": "covered"
    }
  ]
};
describe('Exported Contrast requirements', () => {
  for (const check of spec.checks) {
    if (!check.executable) { test.todo(check.id + ': missing executable observation/adapter integration'); continue; }
    test(check.id + ': ' + check.left + ' ' + check.kind + ' ' + check.right + ' on ' + check.channel, () => {
      const vector = (caseId: string) => check.observationIds.map(id => {
        const o = spec.project.observations.find(item => item.id === id)!;
        const c = spec.project.cases.find(item => item.id === caseId)!;
        const value = normalize(o, observe(o.adapter!, c.input ?? '', o.operation!));
        expect(value).not.toBeNull();
        return value;
      });
      const left = vector(check.left), right = vector(check.right);
      if (check.kind === 'same') expect(left).toEqual(right);
      else expect(left).not.toEqual(right);
    });
  }
});

